import {
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Texture,
  Vector3,
} from 'three/webgpu';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const {
    scenePosition: pos = { x: 0, y: 3, z: 0 },
    sceneRotation: rot = { x: 0, y: 0, z: 0 },
    sceneScale: scale = { x: 1, y: 1, z: 1 },
    imageUrl,
    textContent,
  } = config;

  // Parse text content - expected format: { "body, 31px 400": "text string" }
  let textStr = '';
  let fontSize = 0.31; // fallback
  if (textContent) {
    const keys = Object.keys(textContent);
    if (keys.length > 0) {
      const key = keys[0];
      textStr = textContent[key];
      // Extract pixel size from key (e.g. "body, 31px 400")
      const pxMatch = key.match(/(\d+)px/);
      if (pxMatch) {
        const px = parseFloat(pxMatch[1]);
        // Convert px to scene units (assume 100px = 1 unit)
        fontSize = px / 100;
      }
    }
  }

  // --- Plane (background) ---
  // Use aspect ratio from source rect (512x320 => 1.6:1)
  const planeWidth = 3.2;
  const planeHeight = 2.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const texture = ctx.textureLoader.load(imageUrl);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide, // if needed
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // --- Text overlay ---
  if (textStr && ctx.fontAtlas) {
    const textOptions = {
      font: 'JetBrains Mono',
      fontWeight: 400,
      fontSize: fontSize,
      color: '#16161d', // ink
      align: 'center',
      baseline: 'center',
    };
    const textMesh = ctx.fontAtlas.createText(textStr, textOptions);
    // Position text slightly in front of plane
    textMesh.position.set(0, 0, 0.01);
    textMesh.scale.set(1, 1, 1);
    mesh.add(textMesh);
  }

  // Attach handlers (none)
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture && texture !== undefined) texture.dispose();
    // Dispose children (text meshes)
    mesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  return mesh;
}

export default createNode;
